// This function serves as the primary entry point for processing the given input.
function ProcessInput(rawData) {
  // The incoming data string is first divided into an array of strings, using newline characters as delimiters.
  rawData = rawData.split("\n");

  // We extract the very first element from the processed array, which is expected to be a single character or string.
  var firstChar = rawData[0];

  // The Unicode (or ASCII) value of the initial character is printed to the console.
  console.log(firstChar.charCodeAt(0));

  // A new string is generated by taking the Unicode value of the first character, incrementing it by one,
  // and then converting that new numerical value back into its corresponding character.
  var nextCharStr = String.fromCharCode(firstChar.charCodeAt(0) + 1);

  // The newly generated character string is then displayed on the console.
  console.log('%s', nextCharStr);

  // The function concludes by returning this computed character string.
  return nextCharStr;
}

// This auxiliary function is designed to facilitate the testing of the main processing logic within a web page context.
function testSolution(testCaseIndex) {
  // It retrieves the specific test input data from a DOM element identified by its index.
  var testInputData = document.getElementById("input" + testCaseIndex).value;

  // The main processing function is invoked with this retrieved test data.
  var computedResult = ProcessInput(testInputData);

  // A variable is initialized to store the outcome of the test, defaulting to "Wrong Answer".
  var testOutcome = "WA";

  // The computed result is compared against the expected output, which is also fetched from a DOM element.
  if (computedResult == document.getElementById("output" + testCaseIndex).value.split("\n")[0]) {
    // If the computed result matches the expected output, the test outcome is updated to "Accepted".
    testOutcome = "AC";
  }

  // Finally, the determined test outcome is displayed within another designated DOM element.
  document.getElementById("result" + testCaseIndex).innerHTML = testOutcome;
}

// The primary processing function is executed immediately upon script load,
// using data read synchronously from the standard input stream.
ProcessInput(require("fs").readFileSync("/dev/stdin", "utf8"));
